#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=13

# Everything this wizard captures stays on the laptop, outside the repo.
WAYS_HOME="${WAYS_HOME:-$HOME/.ways}"
mkdir -p "$WAYS_HOME/tls" && chmod 700 "$WAYS_HOME"
ENV_FILE="$WAYS_HOME/fleet.env"
SSH_KEY="$HOME/.ssh/id_rsa"   # replaced by the operator's choice in stage 1
SSH_OPTS=()
PROBE_PORT=40123
ABROADS=(ABROAD1) # gains ABROAD2 if a second Exit is rented in stage 3

# val NAME prints the value of the variable called NAME, or nothing.
val() { local n="$1"; printf '%s' "${!n:-}"; }
lower() { printf '%s' "$1" | tr '[:upper:]' '[:lower:]'; }
remote() { local user="$1" host="$2"; shift 2; ssh "${SSH_OPTS[@]}" "$user@$host" "$@"; }
ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { warn "$1"; return 1; }

# ask_until KEY "Prompt" REGEX "hint" asks until the answer matches.
ask_until() {
  while :; do
    ask "$1" "$2"
    [[ "$(val "$1")" =~ $3 ]] && return 0
    warn "$4"
  done
}

# retry "what" CMD... runs CMD until it passes, or the human moves on.
retry() {
  local what="$1"; shift
  until "$@"; do
    if ! confirm "Fix it and retry? (No moves on and lists it as still to do)"; then
      SKIPPED+=("$what"); return 0
    fi
  done
}

# check_host PREFIX: SSH works with the operator's key, Ubuntu 26.04, passwordless sudo.
check_host() {
  local ip user ver
  ip=$(val "$1_IP"); user=$(val "$1_USER")
  remote "$user" "$ip" true 2>/dev/null || fail "can't SSH to $user@$ip with $SSH_KEY" || return 1
  ok "SSH to $user@$ip works"
  ver=$(remote "$user" "$ip" '. /etc/os-release; echo "$VERSION_ID"')
  [[ "$ver" == "26.04" ]] || fail "it runs Ubuntu $ver, not 26.04: reinstall it with 26.04" || return 1
  ok "Ubuntu 26.04"
  remote "$user" "$ip" 'sudo -n true' 2>/dev/null || fail "$user can't sudo without a password" || return 1
  ok "passwordless sudo"
}

# rent_node PREFIX "where": captures one VM and checks it.
rent_node() {
  local p="$1" org
  ask_until "${p}_NAME" "Short name for this Node (such as $2):" '^[a-z0-9-]+$' "use lowercase letters, digits and dashes"
  ask "${p}_PROVIDER" "Provider (company name):"
  ask_until "${p}_IP" "Public IPv4 address:" '^([0-9]{1,3}\.){3}[0-9]{1,3}$' "that isn't an IPv4 address"
  ask "${p}_USER" "SSH user (root, or a user with passwordless sudo):"
  org=$(curl -fsS -m 10 "https://ipinfo.io/$(val "${p}_IP")/org" 2>/dev/null || true)
  if [[ -n "$org" ]]; then ok "network: $org"; else
    note "couldn't look up its network; find the AS number at https://bgp.he.net/ip/$(val "${p}_IP")"
    ask "${p}_ASN" "AS number and name (such as AS12345 Example):"; org=$(val "${p}_ASN")
  fi
  for k in NAME PROVIDER IP USER; do write_env "${p}_$k" "$(val "${p}_$k")"; done
  write_env "${p}_ASN" "$org"
  retry "$(val "${p}_NAME"): SSH, Ubuntu 26.04 or sudo check" check_host "$p"
}

# gre_tunnel IP USER REMOTE INNER: a throwaway GRE interface on the VM at IP,
# from its own interface address to REMOTE, with INNER as its /30 address.
# Passing no INNER deletes it.
gre_tunnel() {
  local cmd="sudo ip link del wayschk 2>/dev/null; true"
  if [[ -n "${4:-}" ]]; then
    cmd="$cmd; src=\$(ip -4 route get $3 | sed -n 's/.* src \([0-9.]*\).*/\1/p'); sudo modprobe ip_gre;"
    cmd="$cmd sudo ip link add wayschk type gre local \$src remote $3 ttl 64 && sudo ip addr add $4/30 dev wayschk && sudo ip link set wayschk up"
  fi
  remote "$2" "$1" "$cmd" >/dev/null 2>&1
}

# check_crossing PREFIX: a domestic VM reaches both abroad Nodes over UDP on a
# high port and over GRE (IP protocol 47), what Links use (ADR 0009), and
# reaches the web abroad over HTTPS.
check_crossing() {
  local dip duser a aip auser out pid code bad=0 gre_bad=0
  dip=$(val "$1_IP"); duser=$(val "$1_USER")
  for a in "${ABROADS[@]}"; do
    aip=$(val "${a}_IP"); auser=$(val "${a}_USER"); out=$(mktemp)
    remote "$auser" "$aip" "timeout 15 nc -u -l $PROBE_PORT" >"$out" 2>/dev/null & pid=$!
    sleep 3
    remote "$duser" "$dip" "for i in 1 2 3 4 5; do echo ways-probe | nc -u -w1 $aip $PROBE_PORT; sleep 1; done" >/dev/null 2>&1 || true
    wait "$pid" || true
    if grep -q ways-probe "$out"; then ok "UDP $PROBE_PORT reaches $(val "${a}_NAME") ($aip)"
    else warn "UDP from $dip never reached $(val "${a}_NAME") ($aip) on port $PROBE_PORT"; bad=1; fi
    rm -f "$out"
    # GRE both ways: a tunnel between the two public addresses, through
    # any NAT in front of either, and a ping across it from the domestic end.
    gre_tunnel "$aip" "$auser" "$dip" 10.255.255.2
    gre_tunnel "$dip" "$duser" "$aip" 10.255.255.1
    if remote "$duser" "$dip" "ping -c 3 -W 2 10.255.255.2" >/dev/null 2>&1; then ok "GRE reaches $(val "${a}_NAME") ($aip) and back"
    else warn "GRE (IP protocol 47) between $dip and $(val "${a}_NAME") ($aip) doesn't get through"; gre_bad=1; fi
    gre_tunnel "$dip" "$duser"
    gre_tunnel "$aip" "$auser"
  done
  if (( gre_bad )); then
    note "GRE is the first Transport on Links that cross the filter; without it they fall back to UDP."
    note "Check both providers' firewalls (security groups) allow IP protocol 47, or all traffic, between these VMs."
    bad=1
  fi
  code=$(remote "$duser" "$dip" "curl -sS -m 10 -o /dev/null -w '%{http_code}' https://www.cloudflare.com/" 2>/dev/null || true)
  if [[ "$code" =~ ^[23] ]]; then ok "HTTPS abroad works"; else warn "HTTPS abroad failed (got '${code:-nothing}')"; bad=1; fi
  if (( bad )); then
    note "If every abroad Node fails, this datacenter probably only lets allowlisted IPs out: cancel it."
    note "If only one fails, check that Node's provider firewall (and 'sudo ufw status') for UDP $PROBE_PORT."
    return 1
  fi
}

# coord_source PREFIX prints the address the Node sees the Coordinator's
# connections come from on TCP 9443, the monitoring port, or nothing. It
# watches for the SYN, so nothing needs to listen yet. An HTTPS lookup from
# the Coordinator can't tell: some networks send HTTPS abroad through other
# addresses than plain TCP.
coord_source() {
  local ip user out pid
  ip=$(val "$1_IP"); user=$(val "$1_USER"); out=$(mktemp)
  remote "$user" "$ip" "sudo timeout 15 tcpdump -nl -i any -c 1 'tcp dst port 9443 and tcp[tcpflags] & tcp-syn != 0'" >"$out" 2>/dev/null & pid=$!
  sleep 3
  remote "$COORD_USER" "$COORD_IP" "for i in 1 2 3; do nc -z -w2 $ip 9443; sleep 1; done" >/dev/null 2>&1 || true
  wait "$pid" || true
  sed -n 's/.* IP \([0-9.]*\)\.[0-9]* > .*/\1/p' "$out" | head -n1
  rm -f "$out"
}

# check_inbound: the abroad Nodes can open TCP 443 and 8443 on the Coordinator.
check_inbound() {
  local cip cuser a aip auser port pid bad=0
  cip=$(val COORD_IP); cuser=$(val COORD_USER)
  for a in "${ABROADS[@]}"; do
    aip=$(val "${a}_IP"); auser=$(val "${a}_USER")
    for port in 443 8443; do
      remote "$cuser" "$cip" "sudo timeout 15 nc -l $port" >/dev/null 2>&1 & pid=$!
      sleep 3
      if remote "$auser" "$aip" "nc -z -w5 $cip $port" 2>/dev/null; then ok "$(val "${a}_NAME") reaches TCP $port on the Coordinator"
      else warn "$(val "${a}_NAME") can't reach TCP $port on the Coordinator"; bad=1; fi
      kill "$pid" 2>/dev/null || true; wait "$pid" 2>/dev/null || true
    done
  done
  (( bad == 0 )) || { note "Check the Coordinator provider's firewall for inbound 443 and 8443 from abroad."; return 1; }
}

banner "WAYS: provision the production fleet"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Laptop: tools and your SSH key"
say "Everything you enter is saved in $ENV_FILE (mode 0600), never in the repo."
note "If you're in Iran, keep a VPN on for this whole wizard: it calls ipinfo.io and Telegram."
missing=()
for t in ssh curl nc dig openssl age age-keygen; do command -v "$t" >/dev/null 2>&1 || missing+=("$t"); done
if (( ${#missing[@]} )); then
  warn "missing: ${missing[*]}"
  step "Install them (age comes from 'brew install age'), then re-run this wizard."
  exit 1
fi
ok "tools present"
command -v ansible-playbook >/dev/null 2>&1 || note "Ansible isn't installed yet; you'll need it for deploying: brew install ansible"
say "Which SSH key should reach the servers? Your existing key is fine."
ask SSH_KEY "Private key path (Enter for ~/.ssh/id_rsa):"
SSH_KEY="${SSH_KEY:-$HOME/.ssh/id_rsa}"; SSH_KEY="${SSH_KEY/#\~/$HOME}"
[[ -f "$SSH_KEY" && -f "$SSH_KEY.pub" ]] || { warn "no key pair at $SSH_KEY (and $SSH_KEY.pub)"; exit 1; }
if ! ssh-keygen -y -P "" -f "$SSH_KEY" >/dev/null 2>&1 && ! ssh-add -l 2>/dev/null | grep -qF "$(ssh-keygen -lf "$SSH_KEY.pub" | awk '{print $2}')"; then
  warn "the key has a passphrase and isn't in ssh-agent, so the checks can't use it unattended"
  step "Run: ssh-add --apple-use-keychain $SSH_KEY   (then re-run this wizard)"
  exit 1
fi
write_env SSH_KEY "$SSH_KEY"
SSH_OPTS=(-i "$SSH_KEY" -o BatchMode=yes -o ConnectTimeout=10 -o StrictHostKeyChecking=accept-new)
ok "SSH key: $SSH_KEY"
say "Add this public key to every VM you rent (most providers have an SSH keys page):"
printf '\n    %s\n\n' "$(cat "$SSH_KEY.pub")"
command -v pbcopy >/dev/null 2>&1 && pbcopy < "$SSH_KEY.pub" && note "(copied to the clipboard)"
pause "Press Enter once you've saved it with your providers."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Abroad Node 1"
say "Rent the first abroad VM. It will be an Exit."
step "Any provider outside Iran; 1–2 vCPU, 1–2 GB RAM, generous traffic, and a public IPv4."
step "Image: Ubuntu 26.04. Add your SSH key when creating it."
step "If the provider has a cloud firewall, allow inbound UDP (all ports), IP protocol 47 (GRE), TCP 22,"
step "and TCP 9443 (monitoring; the Coordinator scrapes it)."
pause "Press Enter once it's running."
rent_node ABROAD1 "de-1"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Abroad Node 2 (optional)"
say "A second abroad Exit, at a different provider from $(val ABROAD1_PROVIDER), keeps traffic"
say "abroad flowing when one is blocked. You can also add it later: list it under abroad in"
say "the inventory and run enroll.yml for it."
if confirm "Rent a second abroad Node now?"; then
  step "Same size, Ubuntu 26.04, your SSH key, inbound UDP, GRE, TCP 22 and 9443 allowed."
  pause "Press Enter once it's running."
  rent_node ABROAD2 "nl-1"
  ABROADS+=(ABROAD2)
  if [[ "$(lower "$ABROAD2_PROVIDER")" == "$(lower "$ABROAD1_PROVIDER")" ]]; then
    warn "both abroad Nodes are at $ABROAD1_PROVIDER: one provider outage takes out every Exit"
    confirm "Keep it anyway?" || SKIPPED+=("move the second abroad Node to another provider")
  fi
else
  warn "one Exit abroad: if the filter blocks $(val ABROAD1_NAME), Devices lose everything abroad"
  SKIPPED+=("a second abroad Exit at another provider")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Domestic Node 1"
say "Rent the first domestic VM in an Iranian datacenter. It will be a Bridge (tagged IR)."
step "Pick the cheapest hourly or monthly plan first: this stage tests whether it can reach abroad."
step "Ubuntu 26.04, your SSH key, a public IPv4, inbound UDP, GRE, TCP 22 and 9443 allowed."
pause "Press Enter once it's running."
rent_node DOM1 "ir-1"
say "Checking that this VM can reach your abroad Nodes…"
retry "$(val DOM1_NAME): reaching abroad over UDP, GRE and HTTPS" check_crossing DOM1
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Domestic Node 2"
say "Rent the second domestic VM in a datacenter on a different network (AS) from $(val DOM1_NAME)."
note "$(val DOM1_NAME) is on: $(val DOM1_ASN)"
pause "Press Enter once it's running."
rent_node DOM2 "ir-2"
if [[ "${DOM2_ASN%% *}" == "${DOM1_ASN%% *}" ]]; then
  warn "both domestic Nodes are on ${DOM1_ASN%% *}: one network cut takes out both Bridges"
  confirm "Keep it anyway?" || SKIPPED+=("move the second domestic Node to another AS")
fi
say "Checking that this VM can reach your abroad Nodes…"
retry "$(val DOM2_NAME): reaching abroad over UDP, GRE and HTTPS" check_crossing DOM2
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Coordinator VM"
say "Rent the Coordinator VM in Iran, ideally at a provider neither Bridge uses"
say "($(val DOM1_PROVIDER), $(val DOM2_PROVIDER))."
step "2 vCPU, 2–4 GB RAM, 40 GB disk; Ubuntu 26.04; your SSH key."
step "Allow inbound TCP 22, 443 (the panel) and 8443 (Agents)."
pause "Press Enter once it's running."
rent_node COORD "coordinator"
for p in DOM1 DOM2; do
  if [[ "$(lower "$COORD_PROVIDER")" == "$(lower "$(val "${p}_PROVIDER")")" ]]; then
    warn "the Coordinator shares $COORD_PROVIDER with $(val "${p}_NAME") (ADR 0001 prefers another provider)"
  fi
done
say "Checking that Agents abroad can reach it…"
retry "Coordinator: inbound 443 and 8443 from abroad" check_inbound
say "Checking which address each Node sees the Coordinator come from…"
sources=()
for p in DOM1 DOM2 "${ABROADS[@]}"; do
  src=$(coord_source "$p")
  if [[ -z "$src" ]]; then
    warn "$(val "${p}_NAME") saw no connection from the Coordinator on TCP 9443: check its firewall"
    SKIPPED+=("$(val "${p}_NAME"): inbound TCP 9443 from the Coordinator")
    continue
  fi
  ok "$(val "${p}_NAME") sees it as $src"
  [[ " ${sources[*]} " == *" $src "* ]] || sources+=("$src")
done
(( ${#sources[@]} )) || sources=("$COORD_IP")
for src in "${sources[@]}"; do
  [[ "$src" == "$COORD_IP" ]] || warn "a Node sees the Coordinator as $src, not $COORD_IP: monitoring lets that address in too"
done
write_env COORD_EGRESS_IP "$(IFS=,; printf '%s' "${sources[*]}")"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "ArvanCloud: the wayfinder.ir zone"
say "The panel and Agents use wayfinder.ir; the Bridge Address bridge.wayfinder.ir lives in the same zone."
open_url "https://panel.arvancloud.ir"
step "Add the domain wayfinder.ir (CDN service). ArvanCloud then shows you two nameservers."
step "At your .ir registrar (nic.ir or your reseller), set those two nameservers for wayfinder.ir."
step "In ArvanCloud's DNS records for wayfinder.ir, add an A record: name @, value $COORD_IP."
step "Turn the cloud (proxy) icon OFF on that record: Agents need a direct connection on 8443."
note "Don't create bridge yourself: the Coordinator creates it and keeps it to the healthy Bridges."
pause "Press Enter once the A record is saved."
check_dns() {
  local got
  got=$(dig +short A wayfinder.ir @"$(dig +short NS wayfinder.ir | head -n1)" 2>/dev/null | head -n1)
  [[ "$got" == "$COORD_IP" ]] || fail "wayfinder.ir resolves to '${got:-nothing}' via its nameservers, not $COORD_IP (nameserver changes can take hours)" || return 1
  ok "wayfinder.ir → $COORD_IP"
}
retry "DNS: wayfinder.ir A record → Coordinator" check_dns
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "ArvanCloud: API key for the Bridge Address"
say "The Coordinator keeps bridge.wayfinder.ir to the healthy Bridges through ArvanCloud's API."
open_url "https://panel.arvancloud.ir"
step "Open your account menu and find API keys (or machine users). I don't know the exact"
step "menu path in the current panel; ArvanCloud's docs search for 'API key' finds it."
step "Create a key with DNS rights limited to wayfinder.ir if the panel allows that, and copy it."
check_arvan() {
  ask_secret ARVAN_API_KEY "Paste the API key:"
  # The panel shows "apikey <key>"; keep only the key, whatever its case.
  ARVAN_API_KEY="${ARVAN_API_KEY//[[:space:]]/}"
  if [[ "$(lower "${ARVAN_API_KEY:0:6}")" == apikey ]]; then ARVAN_API_KEY="${ARVAN_API_KEY:6}"; fi
  curl -fsS -m 15 -H "Authorization: Apikey $ARVAN_API_KEY" \
    "https://napi.arvancloud.ir/cdn/4.0/domains/wayfinder.ir/dns-records" >/dev/null 2>&1 \
    || fail "ArvanCloud rejected that key for wayfinder.ir" || return 1
  ok "the key can read wayfinder.ir's records"
}
retry "ArvanCloud API key" check_arvan
write_env ARVAN_API_KEY "$ARVAN_API_KEY"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "TLS certificate for wayfinder.ir"
say "The panel needs a public certificate. The simplest route is acme.sh with ArvanCloud's DNS plugin."
TLS_CERT_FILE="$WAYS_HOME/tls/wayfinder.ir.crt"; TLS_KEY_FILE="$WAYS_HOME/tls/wayfinder.ir.key"
open_url "https://github.com/acmesh-official/acme.sh/wiki/dnsapi#dns_arvan"
step "Install acme.sh: brew install acme.sh (or the installer on its README)."
step "Check the wiki page above for the variable the Arvan plugin reads (Arvan_Token)."
step "Then run, on this laptop:"
note "    export Arvan_Token='Apikey <your key>'   # as the wiki says"
note "    acme.sh --issue --server letsencrypt --dns dns_arvan -d wayfinder.ir"
note "    acme.sh --install-cert -d wayfinder.ir --fullchain-file $TLS_CERT_FILE --key-file $TLS_KEY_FILE"
note "Any other CA works too: just put the full chain and key at those two paths."
pause "Press Enter once both files exist."
check_tls() {
  [[ -s "$TLS_CERT_FILE" && -s "$TLS_KEY_FILE" ]] || fail "missing $TLS_CERT_FILE or $TLS_KEY_FILE" || return 1
  openssl x509 -in "$TLS_CERT_FILE" -noout -checkhost wayfinder.ir 2>/dev/null | grep -q "does match" \
    || fail "the certificate isn't valid for wayfinder.ir" || return 1
  ok "certificate for wayfinder.ir, $(openssl x509 -in "$TLS_CERT_FILE" -noout -enddate)"
  chmod 600 "$TLS_KEY_FILE"
}
retry "TLS certificate for wayfinder.ir" check_tls
write_env TLS_CERT_FILE "$TLS_CERT_FILE"
write_env TLS_KEY_FILE "$TLS_KEY_FILE"
note "Let's Encrypt certificates last 90 days; the Coordinator alerts before expiry."
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Telegram: alert bot and channel"
say "Alerts reach you on Telegram, relayed through an Exit."
open_url "https://t.me/BotFather"
step "Send /newbot, pick a name and username, and copy the token BotFather replies with."
ask_secret TELEGRAM_TOKEN "Paste the bot token:"
TELEGRAM_TOKEN="${TELEGRAM_TOKEN//[[:space:]]/}"
step "Create a private Telegram channel for alerts and add the bot as an administrator."
step "Post any message in the channel (such as 'hello')."
pause "Press Enter once you've posted it."
find_chat() {
  TELEGRAM_CHAT=$(curl -fsS -m 15 "https://api.telegram.org/bot$TELEGRAM_TOKEN/getUpdates" 2>/dev/null \
    | grep -oE '"chat":\{"id":-?[0-9]+' | tail -n1 | grep -oE -- '-?[0-9]+$' || true)
  [[ -n "$TELEGRAM_CHAT" ]] || fail "no message seen yet: is the bot an admin of the channel? Post again." || return 1
  curl -fsS -m 15 "https://api.telegram.org/bot$TELEGRAM_TOKEN/sendMessage" \
    --data-urlencode "chat_id=$TELEGRAM_CHAT" --data-urlencode "text=WAYS alerts will arrive here." >/dev/null \
    || fail "the bot couldn't post to chat $TELEGRAM_CHAT" || return 1
  confirm "Did 'WAYS alerts will arrive here.' appear in the channel?" || return 1
  ok "alerts go to chat $TELEGRAM_CHAT"
}
retry "Telegram channel id" find_chat
write_env TELEGRAM_TOKEN "$TELEGRAM_TOKEN"
write_env TELEGRAM_CHAT "${TELEGRAM_CHAT:-}"
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Object storage abroad for backups"
say "The Coordinator pushes one encrypted backup a night to S3-compatible storage abroad."
step "At an abroad provider (not one in Iran), create a private bucket, such as ways-backups."
step "Create an access key limited to that bucket. Write-only, if the provider offers it."
step "Note the S3 endpoint URL and region from the provider's docs."
ask_until BACKUP_S3_ENDPOINT "S3 endpoint (https://…):" '^https://' "it should start with https://"
ask BACKUP_S3_REGION "Region (Enter for us-east-1 if the provider doesn't use regions):"
BACKUP_S3_REGION="${BACKUP_S3_REGION:-us-east-1}"
ask BACKUP_S3_BUCKET "Bucket name:"
ask BACKUP_S3_ACCESS_KEY "Access key id:"
ask_secret BACKUP_S3_SECRET_KEY "Secret key:"
for k in BACKUP_S3_ENDPOINT BACKUP_S3_REGION BACKUP_S3_BUCKET BACKUP_S3_ACCESS_KEY BACKUP_S3_SECRET_KEY; do
  write_env "$k" "$(val "$k")"
done
check_s3() {
  local code
  code=$(remote "$COORD_USER" "$COORD_IP" "curl -sS -m 10 -o /dev/null -w '%{http_code}' $BACKUP_S3_ENDPOINT" 2>/dev/null || true)
  [[ -n "$code" && "$code" != 000 ]] || fail "the Coordinator can't reach $BACKUP_S3_ENDPOINT" || return 1
  ok "the Coordinator reaches $BACKUP_S3_ENDPOINT (HTTP $code)"
}
retry "Coordinator reaching the backup storage" check_s3
note "The credentials themselves are first exercised by the Coordinator's first nightly backup."
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Backup key: age, on this laptop only"
say "Backups are encrypted to a key only you hold. A seized Coordinator can't read them."
BACKUP_AGE_IDENTITY="$WAYS_HOME/backup-identity.txt"
if [[ -f "$BACKUP_AGE_IDENTITY" ]]; then
  ok "reusing $BACKUP_AGE_IDENTITY"
else
  (umask 077 && age-keygen -o "$BACKUP_AGE_IDENTITY" 2>/dev/null)
  ok "created $BACKUP_AGE_IDENTITY"
fi
write_env BACKUP_AGE_IDENTITY "$BACKUP_AGE_IDENTITY"
write_env BACKUP_AGE_RECIPIENT "$(age-keygen -y "$BACKUP_AGE_IDENTITY")"
warn "If this laptop dies, the backups die with it. Store a copy of the file offline now,"
warn "such as in your password manager. Never put it on a server."
until confirm "Have you stored an offline copy of $BACKUP_AGE_IDENTITY?"; do :; done
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Ansible inventory"
INVENTORY="$WAYS_HOME/inventory.yml"
if [[ ! -f "$INVENTORY" ]] || confirm "Overwrite $INVENTORY?"; then
  inv_host() { printf '        %s: {ansible_host: %s, ansible_user: %s}\n' "$(val "$1_NAME")" "$(val "$1_IP")" "$(val "$1_USER")"; }
  {
    printf '# Written by scripts/provision-fleet.sh. Secrets live in fleet.env beside it.\n'
    printf 'all:\n  vars:\n    ansible_ssh_private_key_file: %s\n  children:\n' "$SSH_KEY"
    printf '    coordinators:\n      hosts:\n'; inv_host COORD
    printf '    domestic:\n      hosts:\n';    inv_host DOM1; inv_host DOM2
    printf '    abroad:\n      hosts:\n';      for a in "${ABROADS[@]}"; do inv_host "$a"; done
  } > "$INVENTORY"
  ok "wrote $INVENTORY"
fi
say "Your fleet:"
for p in COORD DOM1 DOM2 "${ABROADS[@]}"; do
  note "  $(printf '%-12s %-15s %s' "$(val "${p}_NAME")" "$(val "${p}_IP")" "$(val "${p}_ASN")")"
done
pause "Press Enter to finish."

finish
say "Next: the deployment playbooks read $INVENTORY and $ENV_FILE."
}

run_wizard "$@"; exit
